// that module can hold its own contract of being free of react-intl.
//
// `partials/staticProductHeader.tsx` declares an identical formatter and that one IS live. The
// two cannot disagree on a rendered price, because only one of them ever formats anything.
const formatPrice = (amount: number, priceCurrency: string) =>
  formatNumber(amount, { style: 'currency', currency: priceCurrency });

// Model copy and the style code are not part of the content group: the design places them at
// the foot of the column, below the accordions, so the page positions them itself.
const staticInfo = selectPdpProductInfo(product, null, product?.currency ?? '', formatPrice);

return (
  <Box className="sf-product-detail-page" layerStyle="page" data-testid="product-details-page">
    <Heading as="h1" srOnly>
      <FormattedMessage defaultMessage="Product Details" id="product_detail.title.product_details" />
    </Heading>
    <Helmet>
      <title>{product?.pageTitle}</title>
      {product?.pageMetaTags?.length > 0 &&
        product.pageMetaTags.map(({ id, value }: { id: string; value: string }) => (
          <meta name={id} content={value} key={id} />
        ))}
      {/* Fallback for description if not included in pageMetaTags */}
      {!product?.pageMetaTags?.some((tag: { id: string }) => tag.id === 'description') &&
        product?.pageDescription && <meta name="description" content={product.pageDescription} />}
    </Helmet>

    <Stack spacing={16}>
      {isProductASet || isProductABundle ? (
        <Fragment>
          <Island hydrateOn={'visible'}>
            <ProductView
              product={product}
              category={primaryCategory?.parentCategoryTree || []}
              addToCart={isProductASet ? handleProductSetAddToCart : handleProductBundleAddToCart}
              addToWishlist={handleAddToWishlist}
              isProductLoading={isProductLoading}
              isBasketLoading={isBasketLoading}
              isWishlistLoading={isWishlistLoading}
              validateOrderability={handleChildProductValidation}
              childProductOrderability={childProductOrderability}
              setSelectedBundleQuantity={setSelectedBundleQuantity}
              selectedBundleParentQuantity={selectedBundleQuantity}
              pickupInStore={!!pickupInStoreMap[product?.id]}
              setPickupInStore={(checked: boolean) => product && handlePickupInStoreChange(product.id, checked)}
              onOpenStoreLocator={onOpenStoreLocator}
              showDeliveryOptions={storeLocatorEnabled}
            />
          </Island>

          <hr />

          {
            // Render the child products
            product?.childProducts?.map(
              ({ product: childProduct, quantity: childQuantity }: { product: SfccProduct; quantity: number }) => (
                <Box key={childProduct.id} data-testid="child-product">
                  <ProductView
                    // Do not use an arrow function as we are manipulating the functions scope.
                    ref={function (this: ProductViewRefScope, ref: ChildProductRef['ref']) {
                      // Assign the "set" scope of the ref, this is how we access the internal
                      // validation.
                      childProductRefs.current[childProduct.id] = {
                        ref,
                        validateOrderability: this.validateOrderability,
                      };
                    }}
                    product={childProduct}
                    isProductPartOfSet={isProductASet}
                    isProductPartOfBundle={isProductABundle}
                    childOfBundleQuantity={childQuantity}
                    selectedBundleParentQuantity={selectedBundleQuantity}
                    addToCart={
                      isProductASet
                        ? (productSelectionValues: ProductSelectionValue[]) => handleAddToCart(productSelectionValues)
                        : null
                    }
                    addToWishlist={isProductASet ? handleAddToWishlist : null}
                    onVariantSelected={(product: SfccProduct, variant: SfccVariant, quantity: number) => {
                      if (quantity) {
                        setChildProductSelection((previousState) => ({
                          ...previousState,
                          [product.id]: {
                            product,
                            variant,
                            quantity: isProductABundle ? childQuantity : quantity,
                          },
                        }));
                      } else {
                        const selections = {
                          ...childProductSelection,
                        };
                        delete selections[product.id];
                        setChildProductSelection(selections);
                      }
                    }}
                    isProductLoading={isProductLoading}
                    isBasketLoading={isBasketLoading}
                    isWishlistLoading={isWishlistLoading}
                    setChildProductOrderability={setChildProductOrderability}
                    pickupInStore={!!pickupInStoreMap[childProductSelection[childProduct?.id]?.variant?.productId]}
                    setPickupInStore={(checked: boolean) =>
                      childProduct &&
                      handlePickupInStoreChange(childProductSelection[childProduct?.id]?.variant?.productId, checked)
                    }
                    onOpenStoreLocator={onOpenStoreLocator}
                    showDeliveryOptions={storeLocatorEnabled && !isProductABundle}
                  />
                  <InformationAccordion product={childProduct} />

                  <Box display={['none', 'none', 'none', 'block']}>
                    <hr />
                  </Box>
                </Box>
              ),
            )
          }
        </Fragment>
      ) : (
        <Fragment>
          <Island hydrateOn={'visible'}>
            <ProductView
              product={product}
              category={primaryCategory?.parentCategoryTree || []}
              renderHeader={(headerProps) => {
                return (
                  <StaticProductHeader
                    {...headerProps}
                    priceData={isPriceStale ? null : variantScopedPriceData ?? headerProps.priceData}
                    isPriceLoading={isPriceStale}
                  />
                );
              }}
              renderVariationAttribute={(attr) =>
                attr.id === COLOUR_VARIATION_ATTRIBUTE_ID ? (
                  <ZimmColourSwatchGroup
                    label={attr.name ?? ''}
                    selectedName={attr.selectedValue?.name}
                    selectedValue={attr.selectedValue?.value}
                    values={attr.values.map((v) => ({
                      value: v.value ?? '',
                      name: v.name,
                      href: v.href,
                      imageUrl: v.image?.disBaseLink || v.image?.link,
                    }))}
                  />
                ) : undefined
              }
              addToCart={handleAddToCart}
              addToWishlist={handleAddToWishlist}
              isProductLoading={isProductLoading}
              isBasketLoading={isBasketLoading}
              isWishlistLoading={isWishlistLoading}
              childProductOrderability={childProductOrderability}
              setChildProductOrderability={setChildProductOrderability}
              setSelectedBundleQuantity={setSelectedBundleQuantity}
              selectedBundleParentQuantity={selectedBundleQuantity}
              pickupInStore={!!pickupInStoreMap[product?.id]}
              setPickupInStore={(checked: boolean) => product && handlePickupInStoreChange(product.id, checked)}
              onOpenStoreLocator={onOpenStoreLocator}

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Link as RouteLink } from 'react-router-dom';

const ZIMM_COLOUR_SWATCH_RECIPE = 'ZimmColourSwatch';

// Same import base SFCC's own swatch-group/swatch.jsx uses for its `RouteLink` — a router
// `Link` is what actually delivers "URL updates without a full page reload": it pushes history
// rather than navigating the document. There is no overrides/.../link equivalent to reuse
// instead — confirmed none exists for this.
const ColourSwatchLink = chakra(RouteLink);

type ZimmColourSwatchProps = {
  /** Colour display name. Not rendered as visible text — used as the accessible name (`aria-label`). */
  name: string;
  /**
   * Fully resolved image URL for this colour's swatch fill. Resolution is the caller's job —
   * this component performs no SFCC-shape lookup of its own.
   */
  imageUrl: string;
  /**
   * Destination URL for this colour variation. Absent for the quick-view-modal path, where
   * SFCC's own `useVariationAttributes` returns `href: null` and the swatch must not navigate.
   */
  href?: string;
  /** Whether this is the currently selected colour. */
  isSelected: boolean;
  /**
   * Whether this swatch is reachable via Tab (`tabIndex={0}`) vs. removed from the tab order
   * (`tabIndex={-1}`) — the caller drives a roving tabindex across the swatch group.
   */
  isFocusable: boolean;
};

/**
 * Atom — a single colour swatch in a PDP colour-variation list: a clickable rectangle filled
 * with that colour's product photo, radio semantics (one selection out of the group), and a
 * router `Link` when a destination URL exists so selecting a colour updates the URL without a
 * full page reload.
 *
 * Purely presentational — no data-fetching hook of any kind. SFCC data resolution (building
 * `imageUrl`/`href` from a product's variation attributes) happens at the page level, not this
 * atom.
 */
export const ZimmColourSwatch = ({ name, imageUrl, href, isSelected, isFocusable }: ZimmColourSwatchProps) => {
  // Above any early return — there isn't one here, this component always renders something.
  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_RECIPE, { selected: isSelected });

  // The dynamic URL genuinely cannot live in the static recipe file, so this one dynamic `__css`
  // spread is the correct, deliberate exception — the same shape already used at
  // footer/footerNavColumn/index.tsx:44 and :62, an established pattern in this codebase.
  const image = <chakra.span __css={{ ...styles.image, backgroundImage: `url(${imageUrl})` }} />;

  /*
   * Deliberately no `backgroundColor={name.toLowerCase()}` here, unlike base SFCC's own
   * `renderDefaultVariationAttribute` (product-view/index.jsx, and our own extraction of it in
   * product-view/index.tsx). Three reasons this stays out, permanently, not an oversight to
   * "fix" back in later:
   *   1. It uses the colour's display name as a raw CSS colour keyword — "Ivory" resolves as a
   *      real CSS colour, "Bay Blue" does not — which is both unauditable by `audit:tokens` and
   *      against this codebase's no-raw-design-value rule.
   *   2. In base it exists to tint the swatch behind a *missing* product image. This component is
   *      only ever rendered for colour variations that already have a populated image — the
   *      caller filters out any variation without one before rendering this component at all —
   *      so there is never a missing image for a fallback tint to show behind.
   *   3. Even if one slipped through, `background-size: cover` on the image (see the recipe's
   *      `image` part) would hide any tint sitting behind it regardless.
   */
  if (href) {
    return (
      <ColourSwatchLink
        to={href}
        __css={styles.swatch}
        role="radio"
        aria-checked={isSelected}
        aria-label={name}
        tabIndex={isFocusable ? 0 : -1}
        data-testid="colour-swatch"
      >
        {image}
      </ColourSwatchLink>
    );
  }

  return (
    <chakra.span
      __css={styles.swatch}
      data-testid="colour-swatch"
    >
      {image}
    </chakra.span>
  );
};

// Shared between this molecule's own files (index.tsx, its co-located recipe
// zimmColourSwatchGroup.css.ts, and its test file index.test.tsx) so this value can't drift the
// way five independently-typed literal `4`s already had. Not a general-purpose theme module —
// scope stays this component only; follows the same shared-module precedent
// theme/components/footerShared.ts already sets for a value more than one co-located file needs.

/**
 * Swatches shown per pagination page. Figma's own interaction annotation on this node:
 * "Pagination appears if there are more than 4 swatches."
 */
export const SWATCHES_PER_PAGE = 4;

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for a single PDP colour swatch — a clickable rectangle filled with that colour
 * variation's product photo. Two parts: `swatch` is the outer clickable box (geometry,
 * background, border, focus ring); `image` is the element carrying the dynamic
 * background-image fill — the URL itself cannot live here, see the component's own comment on
 * why that one `__css` spread stays dynamic.
 *
 * Values below are read directly off Figma for the three states this recipe distinguishes, not
 * estimated from surrounding metadata — Unselected (node 40000307:13826), Selected
 * (40000307:13831), Focus (40002689:3839), all under `size=Large/Rectangle`.
 */
export const ZimmColourSwatch = {
  parts: ['swatch', 'image'],

  baseStyle: ({ selected }: { selected?: boolean }): Record<string, SystemStyleObject> => ({
    swatch: {
      display: 'inline-block',
      cursor: 'pointer',
      // Figma's Rectangle width (48px). Height (72px) has no direct token — the named scale has
      // nothing between 64px and 140px — so it's expressed as an aspect ratio on the width
      // instead. 2:3, not the incidentally different ratio Figma's raw code-gen attached to the
      // placeholder product photo pasted into that frame instance: the Selected-state node
      // carries its own dev annotation reading "Image aspect ratio - 2:3", which is the number
      // to trust here.
      width: 'var(--zimm-scale-1200)',
      aspectRatio: '2 / 3',
      // Identical across Unselected/Selected/Focus — ivory[200] / background['02'] in
      // theme/foundation/colour.ts.
      backgroundColor: 'var(--zimm-color-bg-02)',
      // Selected: a bottom-only border — the raw Figma export is unambiguous, a `border-b`
      // utility rather than a full box border. Colour is grey[900] / border.focus, the only
      // alias-tier value that resolves to it (border.default and border.secondary are both
      // light greys and never appear anywhere in this design).
      ...(selected
        ? {
            borderBottomWidth: 'var(--zimm-border-width-default)',
            borderBottomStyle: 'solid',
            borderBottomColor: 'var(--zimm-color-border-focus)',
          }
        : {}),
      // Focus: Figma draws this as the Selected baseline plus a ring at slightly asymmetric
      // per-side offsets, same colour. Not replicated literally — there is no other precedent
      // anywhere in this codebase for a non-uniform ring, and the asymmetry reads as that one
      // frame instance's export noise rather than a deliberate design decision. Mirrors
      // zimmNavItem.css.ts's own focus-ring block instead: a uniform `outline` + `outlineOffset`
      // pair, applied independently of `selected` above — a swatch can be focused without being
      // selected, and selected without being focused. `--zimm-focus-ring` already composites the
      // same border-width/colour pair used above; `--zimm-focus-ring-offset-default` matches
      // three of Figma's four side offsets.
      //
      // `position: relative` + `zIndex: 1`, scoped to this focus-visible state only: the parent
      // `swatches` row (zimmColourSwatchGroup.css.ts) is `gap: 0`, so adjacent swatches sit
      // flush. `outlineOffset` is positive, so the ring paints *outside* this swatch's own
      // border box — and with zero gap, that outward ring overlaps the very next swatch's own
      // box. Both swatches are plain in-flow flex items (`position: static`, `z-index: auto`),
      // so painting follows tree order: the later sibling paints its opaque background on top
      // of the earlier swatch's ring wherever the two overlap, hiding exactly the shared
      // (right-hand) edge — confirmed in a real Chromium render, before this fix, via
      // `getBoundingClientRect`/`elementFromPoint` and a screenshot: the right edge and the
      // right-hand slivers of the top/bottom edges were missing for every swatch with a
      // right-hand sibling, while the last swatch in a row (nothing to its right) rendered a
      // complete rectangle. `zIndex` lifts this swatch into a later, higher paint layer so its
      // ring is no longer covered; `position: relative` is what makes `zIndex` apply here at
      // all for a *general* in-flow, non-positioned element — without it `z-index` is ignored
      // per spec. (A `swatch` specifically is also a direct flex item of `swatches`, and the
      // Flexbox spec carves out flex items as one exception where `z-index` alone establishes
      // a stacking context even while `position` stays `static` — confirmed empirically here
      // too, `z-index` alone did already fix this swatch's own outline. `position: relative` is
      // kept anyway: it costs nothing — no `top`/`left`/etc. offset is set, so it does not move
      // the box — and it keeps this rule correct even if `swatch` is ever composed inside a
      // non-flex parent, rather than depending on a layout detail owned by a sibling file.)
      // Neither property is set outside `_focusVisible`, so normal (unfocused) stacking is
      // completely unaffected.
      _focusVisible: {
        position: 'relative',
        zIndex: 1,
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
    image: {
      display: 'block',
      width: '100%',
      height: '100%',
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      backgroundRepeat: 'no-repeat',
    },
  }),
};

import type { SystemStyleObject } from '@chakra-ui/react';
import { SWATCHES_PER_PAGE } from './zimmColourSwatchGroupShared';

/**
 * Recipe for the PDP colour-swatch group — the "Colour: Bay Blue" label row, and (when there is
 * more than one populated colour) the row of ZimmColourSwatch rectangles beneath it. This recipe
 * only lays the group out; each swatch's own fill/border/focus styling stays in the sibling
 * ZimmColourSwatch atom's own recipe.
 *
 * Values below are read directly off Figma for this exact component, not estimated — node
 * 40000307:13867 ("ColourOptions"), within Zimmermann_Design_System_2026.
 *
 * Six parts:
 *   - `root` — outer vertical flex container: the label row above, the swatches row below.
 *     Capped to a fixed `maxWidth` (`GROUP_RESERVED_WIDTH`, see below) unconditionally — not just
 *     when paginated — so `labelName`'s truncation CSS always has a definite width to truncate
 *     against. See this part's own baseStyle comment for the full explanation.
 *   - `label` — the label row ("labelContainer" in Figma): the label-group (the two
 *     "Colour:"/name text pieces — laid out via a plain Chakra-prop wrapper in the component
 *     itself, not a seventh part here; see index.tsx's own comment for why) plus the pagination
 *     controls, right-aligned purely via the label-group's own `flex: 1 0 0` rather than an
 *     absolute-position hack.
 *   - `labelName` — the dynamic colour-name text specifically (e.g. "Bay Blue"). Gets its own
 *     part, unlike the static "Colour:" piece beside it, because it alone carries the
 *     Figma-mandated truncation behaviour: "If Label/Colour name is longer, use truncation"
 *     (this node's own interaction annotation).
 *   - `swatches` — the horizontal row of rendered ZimmColourSwatch children. Once paginated
 *     (`isPaginated`), reserves a fixed page-width footprint regardless of how many items the
 *     current window actually renders — see its own baseStyle comment below for the layout bug
 *     this prevents.
 *   - `pagination` — wrapper around the two chevron buttons.
 *   - `pageButton` — each individual chevron button (24x24, holding a 16px ZimmIcon).
 */

/**
 * Imported from the shared zimmColourSwatchGroupShared.ts module — the same shared-module
 * precedent theme/components/footerShared.ts already sets — rather than retyped here, so
 * index.tsx, this recipe, and the test file can never disagree with each other. Aliased to the
 * shorter `PAGE_SIZE` name since this file's only use is the `GROUP_RESERVED_WIDTH` calc
 * expression below.
 */
const PAGE_SIZE = SWATCHES_PER_PAGE;

/**
 * The reserved 4-swatch-wide footprint: PAGE_SIZE swatches at the atom's own fixed 48px width
 * (`--zimm-scale-1200` — see zimmColourSwatch.css.ts's `swatch.width`), with no per-swatch gap
 * (`swatches.gap` below is 0, same as the atom's own adjacency). Two consumers share this one
 * value rather than each typing their own copy of the same `calc(...)` expression:
 *   - `swatches.width`/`minWidth`, applied only once paginated (see that part below) — keeps the
 *     footprint constant across a full page vs. a shorter final page.
 *   - `root.maxWidth`, applied unconditionally regardless of pagination (see that part below) —
 *     caps the whole component so `labelName`'s truncation CSS always has a definite width to
 *     truncate against.
 */
const GROUP_RESERVED_WIDTH = `calc(${PAGE_SIZE} * var(--zimm-scale-1200))`;

export const ZimmColourSwatchGroup = {
  parts: ['root', 'label', 'labelName', 'swatches', 'pagination', 'pageButton'],

  baseStyle: ({ isPaginated }: { isPaginated?: boolean }): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      flexDirection: 'column',
      // 8px between the label row and the swatches row. No background here — background lives
      // per-swatch, already handled by the atom's own recipe.
      gap: 'var(--zimm-scale-xs)',
      // Unconditional cap, regardless of `isPaginated` — this is a bug fix, not a stylistic
      // choice. `root` otherwise has no width of its own (deliberate — see the `swatches` part
      // below for why a short, non-paginated row must still size naturally to its actual content)
      // so it has no ceiling for `labelName`'s truncation CSS to truncate against: confirmed via
      // real Chromium rendering that a long enough colour name simply grows `root` (and the
      // flex-grown `labelName` span inside it) past this footprint with no ellipsis, unless some
      // ancestor happens to impose a definite width of its own. Capping `root` itself to the same
      // reserved footprint `swatches` already reserves once paginated makes truncation
      // self-contained in every context, rather than depending on whatever the eventual PDP page
      // does or doesn't constrain. `maxWidth`, not `width`: `root` must still be free to render
      // narrower than this when content is short (e.g. one or two short colour names) — this only
      // ever stops it from growing past the cap. Does not change the swatches row's own sizing
      // behaviour (still `100%` when non-paginated, see below) — it only changes what that `100%`
      // now resolves against.
      maxWidth: GROUP_RESERVED_WIDTH,
    },

    label: {
      display: 'flex',
      alignItems: 'center',
      // 24px. Matches spacing.xl exactly, so the named step is used rather than the numerically
      // identical --zimm-scale-600 alias — see bottomBar.css.ts's own `var(--zimm-scale-xl)`
      // usage for the same 24px value elsewhere in this codebase.
      height: 'var(--zimm-scale-xl)',
      // 8px between the label-group and the pagination controls.
      gap: 'var(--zimm-scale-xs)',
    },

    labelName: {
      textStyle: 'caption',
      color: 'var(--zimm-color-text-default)',
      // The truncating half of the label-group's two text pieces (the static "Colour:" text
      // beside it never truncates — see index.tsx). `flex: 1 0 0` lets it consume the
      // label-group's remaining width; `minWidth: 0` is required for a flex item to actually
      // shrink below its content size instead of overflowing; the rest is the standard
      // single-line-ellipsis triad.
      flex: '1 0 0',
      minWidth: 0,
      overflow: 'hidden',
      textOverflow: 'ellipsis',
      whiteSpace: 'nowrap',
    },

    swatches: {
      display: 'flex',
      // Non-paginated (<= SWATCHES_PER_PAGE populated colours): sizes naturally to however many
      // swatches are actually present. Unchanged, deliberately out of scope for this fix — there
      // is no confirmed design value either way for a 2- or 3-colour row's width, so nothing was
      // invented here.
      //
      // Paginated (> SWATCHES_PER_PAGE populated colours, windowed to a fixed PAGE_SIZE-wide
      // slice per page): a plain `100%` here resolves against `root`'s own width — but `root` has
      // no explicit width of its own, so it auto-fits to its widest child, which is this very
      // element. That circular relationship meant the *rendered* width tracked how many items the
      // current window actually held (192px for a full 4-item page, 96px for a 2-item final
      // page), so `root` — and `label` above it, itself 100% of that same `root` — visibly
      // resized between pages. Confirmed directly in a running Storybook: the pagination chevrons
      // jumped position between the two pages of the `Paginated` story. Reserving
      // GROUP_RESERVED_WIDTH regardless of the current page's real item count breaks that
      // loop — the footprint stays constant across every page, full or partial. A partial final
      // page's unused space simply remains empty to the right: the flex default
      // `justify-content: flex-start` already left-aligns the rendered items, so nothing further
      // is needed for that.
      width: isPaginated ? GROUP_RESERVED_WIDTH : '100%',
      ...(isPaginated ? { minWidth: GROUP_RESERVED_WIDTH } : {}),
      // Confirmed directly off the Figma export, not a stylistic default: the 4-swatch example
      // measures exactly 192px total width for four 48px-wide swatches (4 x 48, no gap
      // contribution) — swatches sit directly adjacent. Do not add a gap here; that would be a
      // real deviation from the design, not a stylistic default.
      gap: 0,
    },

    pagination: {
      display: 'flex',
      alignItems: 'center',
      // No inter-button gap value exists in the Figma export handed to this step — left at the
      // flex default (no `gap` declared at all) rather than invented. Revisit if a designer
      // confirms a real value.
    },

    pageButton: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: 'var(--zimm-scale-xl)', // 24px
      height: 'var(--zimm-scale-xl)', // 24px
      // Resets the native <button> UA chrome so the box is exactly the 24x24 the design calls
      // for, with the 16px ZimmIcon centred inside it by the flex alignment above.
      padding: 0,
      border: 'none',
      background: 'none',
      cursor: 'pointer',
      // No confirmed Figma spec for a disabled visual treatment on this control — same "leave an
      // unspecified visual state alone rather than invent one" precedent as swatch-group's own
      // disabled colour logic (see this codebase's Known Gaps notes). The native `disabled`
      // attribute (set in index.tsx) already makes the control genuinely inert and announces as
      // disabled to assistive tech; only the cursor affordance is set here, which is a UX
      // keyword, not a design token.
      _disabled: {
        cursor: 'not-allowed',
        color: 'var(--zimm-color-icon-disabled)',
      },
      // Same uniform ring every other interactive control in ui-kits/ uses (zimmColourSwatch,
      // zimmNavItem) — --zimm-focus-ring already composites the border-width/colour pair.
      _focusVisible: {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
  }),
};

